import pendulum

from airflow.sdk import dag, task


@dag(schedule="@daily", start_date=pendulum.datetime(2026, 3, 1, tz="UTC"))
def orders_taskflow():
    @task
    def extract():
        return [{"order_id": 1, "amount": 10.0}]

    @task
    def transform(rows):
        return [row for row in rows if row["amount"] > 0]

    @task
    def load(rows):
        print(f"loading {len(rows)} rows")

    @task
    def audit():
        print("audit done")

    raw = extract()
    clean = transform(raw)
    load(clean)
    audit()


orders_taskflow()
